const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID(),clone=o=>JSON.parse(JSON.stringify(o)),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),slug=s=>String(s).replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'')||'Untitled-world';
const TYPES=['Character','Place','Faction','Culture','Species','Religion','Magic / science','Object','Language','Economy','Law & government','Ecology','Cosmology','Food & agriculture','Architecture','Technology','Tradition','Conflict','Custom'];
const PROMPTS={Character:['Desire','Fear','Strength','Flaw','Appearance','Voice','Arc'],Place:['Landscape','Population','Government','Trade','Atmosphere','A secret'],Faction:['Purpose','Leadership','Resources','Allies','Rivals'],Culture:['Values','Traditions','Food','Art','Taboos'],Species:['Appearance','Habitat','Abilities','Life cycle'],Religion:['Beliefs','Rituals','Symbols','Divisions'],'Magic / science':['Rules','Limits','Cost','Who has access'],Object:['Origin','Purpose','Material','Current owner'],Language:['Speakers','Writing system','Sounds','Expressions'],Custom:['Purpose','Details']};
const GENRES={fantasy:{name:'Fantasy',tag:'Kingdoms, magic and strange horizons.',world:'The Lantern Coast',kind:'Fantasy',entry:'Keeper of the Last Light',place:'Lantern Harbour',faction:'The Tidebound Guild',theme:'parchment',summary:'A coast where the sea returns things people thought they had lost.',magic:'What does magic cost, and who pays it?',story:'The light goes out'},scifi:{name:'Science fiction',tag:'Distant worlds, systems and discoveries.',world:'The Quiet Orbit',kind:'Science fiction',entry:'Station Cartographer',place:'Meridian Station',faction:'The Survey Assembly',theme:'blueprint',summary:'A remote station receives a signal from a world absent from every chart.',magic:'What can technology do, and what can it never solve?',story:'The uncharted signal'},horror:{name:'Horror',tag:'Unease, hidden truths and consequences.',world:'The Hollow Parish',kind:'Horror',entry:'The Returning Archivist',place:'Bellweather',faction:'The Night Committee',theme:'night',summary:'A town keeps meticulous records of people who have never existed.',magic:'What is the threat, and how is it misunderstood?',story:'A name in the ledger'},historical:{name:'Historical',tag:'People, power and a changing society.',world:'The River Provinces',kind:'Historical',entry:'The Printer’s Apprentice',place:'Stonebridge',faction:'The River Council',theme:'atlas',summary:'A river city stands at a turning point in trade, politics and communication.',magic:'Which facts require research, and which are fictional?',story:'The forbidden edition'},contemporary:{name:'Contemporary',tag:'Everyday places, relationships and change.',world:'Westward Days',kind:'Contemporary',entry:'The New Neighbour',place:'Westward',faction:'The Community Workshop',theme:'ink',summary:'A neighbourhood changes as its residents decide what is worth keeping.',magic:'What social pressures shape everyday life?',story:'The closing notice'},blank:{name:'Blank world',tag:'Your own categories. Your own beginning.',world:'Untitled world',kind:'Custom',theme:'parchment',summary:''}};
const THEMES={parchment:{name:'Old parchment',sea:'#d8d5b6',land:'#eadbb1',mountain:'#806b4b',forest:'#68805c',ink:'#59452c',route:'#a26b46'},atlas:{name:'Field atlas',sea:'#b8ced1',land:'#e5e8ce',mountain:'#79816b',forest:'#73946d',ink:'#344c45',route:'#ae6950'},blueprint:{name:'Celestial chart',sea:'#183b51',land:'#285a6c',mountain:'#9ebfc5',forest:'#4e8c96',ink:'#e4eacc',route:'#e6b96e'},night:{name:'Midnight',sea:'#20232c',land:'#41464b',mountain:'#949786',forest:'#525f57',ink:'#dfd6b8',route:'#b47d73'},ink:{name:'Ink & paper',sea:'#f5f1e6',land:'#e3dfd1',mountain:'#54574c',forest:'#929888',ink:'#2c3830',route:'#8e5f4a'},rose:{name:'Storybook',sea:'#c9dcd5',land:'#ead7c1',mountain:'#b18176',forest:'#789783',ink:'#614943',route:'#ad6874'}};
const SYMBOLS={town:{name:'Town',glyph:'⌂'},capital:{name:'Capital',glyph:'♜'},mountain:{name:'Mountain',glyph:'▲'},forest:{name:'Forest',glyph:'♠'},ruin:{name:'Ruin',glyph:'♜'},port:{name:'Port',glyph:'⚓'},landmark:{name:'Landmark',glyph:'✦'},danger:{name:'Danger',glyph:'◇'},camp:{name:'Camp',glyph:'△'}};
let brushSize=30,brushSpacing=24;
let world,view='home',selectedEntry=null,selectedDoc=null,selectedMap=null,entryTab='write',entryFilter='All',listQuery='',docView='write',mapTool='select',mapSelection=null,mapSymbol='town',mapShow={terrain:true,regions:true,routes:true,symbols:true,labels:true,grid:false,guides:false},mapViewport=null,mapDraft=[],history=[],future=[],savedSignature='',autosaveTimer,toastTimer,pendingSave=null,lastRecovery=null;
const NAV=[['home','⌂','Overview'],['entries','▤','World library'],['writing','✎','Writing desk'],['timeline','◷','Timeline'],['maps','⌖','Map studio'],['connections','⌘','Connections'],['assets','▧','Assets'],['settings','⚙','World settings']];
function newEntry(type='Character',name='Untitled '+type){return {id:uid(),type,name,summary:'',body:'',secret:'',status:'Draft',tags:[],fields:Object.fromEntries((PROMPTS[type]||PROMPTS.Custom).map(x=>[x,''])),references:[],created:Date.now(),updated:Date.now()};}
function blankWorld(){return {format:'jago-world-project',version:1,id:uid(),name:'Untitled world',genre:'Custom',description:'',premise:'',tone:'',calendar:'Years',notes:'',entries:[],relations:[],documents:[],events:[],maps:[],assets:[],customTypes:[],created:Date.now(),updated:Date.now()};}
function rng(seed){let n=2166136261;for(const c of String(seed))n=Math.imul(n^c.charCodeAt(0),16777619);return()=>{n+=0x6D2B79F5;let t=Math.imul(n^n>>>15,1|n);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296;};}
function generateTerrain(seed,width,height,style='islands',density=65){const rand=rng(seed),lands=[],decor=[];let n=style==='continent'?1:style==='archipelago'?7:3;for(let k=0;k<n;k++){const cx=width*(n===1?.5:.2+rand()*.6),cy=height*(.25+rand()*.5),rx=width*(n===1?.39:n===3?.15+rand()*.1:.07+rand()*.075),ry=height*(n===1?.37:.12+rand()*.18),phase=rand()*6.28;const pts=[];for(let i=0;i<100;i++){const a=i/100*Math.PI*2,r=1+.13*Math.sin(a*3+phase)+.09*Math.sin(a*7+phase)+.04*Math.sin(a*13);pts.push([cx+Math.cos(a)*rx*r,cy+Math.sin(a)*ry*r]);}lands.push(pts);for(let i=0;i<density;i++){const a=rand()*6.28,r=Math.sqrt(rand())*.72;decor.push({x:cx+Math.cos(a)*rx*r,y:cy+Math.sin(a)*ry*r,kind:rand()>.5?'forest':'mountain',size:8+rand()*14});}}return {lands,decor,seed:String(seed),style,density};}
function makeMap(name='New map',theme='parchment'){const m={id:uid(),name,width:1600,height:1000,theme,terrain:null,objects:[],background:null,description:''};m.terrain=generateTerrain('lantern-27',m.width,m.height);return m;}
function makeStarter(key){const g=GENRES[key]||GENRES.blank,w=blankWorld();w.name=g.world;w.genre=g.kind;w.description=g.summary;if(key==='blank')return w;const p=newEntry('Place',g.place),c=newEntry('Character',g.entry),f=newEntry('Faction',g.faction),rule=newEntry('Magic / science',key==='historical'?'Research & inventions':'Rules of the world');p.summary='A place with something worth protecting and something it would rather forget.';p.body='## First impressions\nWhat do you notice when you arrive?\n\n## Daily life\nWho lives here, and what keeps the place alive?';c.summary='A person caught between a private wish and a public responsibility.';c.fields.Desire='To find out what changed.';c.fields.Fear='Losing the place they call home.';c.body='Their story begins in [['+p.name+']].\n\nWhat would force them to act?';f.summary='People united by a purpose, divided by their methods.';rule.summary=g.magic;w.entries=[c,p,f,rule];w.relations=[{id:uid(),from:c.id,to:p.id,label:'lives in'},{id:uid(),from:c.id,to:f.id,label:'connected to'}];w.documents=[{id:uid(),name:'World premise',kind:'Reference',status:'Draft',body:g.summary+'\n\n## The central question\nWhat is changing, and why does it matter?',links:[p.id],order:0},{id:uid(),name:g.story,kind:'Scene',status:'Draft',body:'## Opening image\n\n## What changes\n\n## The choice\n',links:[c.id,p.id],goal:'Introduce a disruption',conflict:'',order:1}];w.events=[{id:uid(),name:'The founding',year:0,date:'',body:'What happened, and who tells this story differently?',links:[p.id],visibility:'Public'},{id:uid(),name:'The story begins',year:100,date:'',body:'Something changes.',links:[c.id],visibility:'Public'}];const m=makeMap('The known world',g.theme);m.objects.push({id:uid(),kind:'symbol',symbol:'port',x:790,y:540,size:30,rotation:0,color:THEMES[g.theme].ink,label:p.name,entryId:p.id,layer:'symbols'});w.maps=[m];w.premise=g.summary;w.notes='Starter prompts are invitations, not rules. Change or delete anything.';return w;}
Object.assign(PROMPTS,{'Economy':['Currency','Trade routes','Labour','Resources','Inequality'],'Law & government':['Authority','Rights','Enforcement','Punishments','Succession'],'Ecology':['Climate','Habitats','Food webs','Resources','Environmental pressures'],'Cosmology':['Origins','Celestial bodies','Time','Death & afterlife','Unknowns'],'Food & agriculture':['Staples','Farming','Seasonality','Cooking','Scarcity'],'Architecture':['Materials','Climate adaptations','Public spaces','Homes','Symbolism'],'Technology':['Capability','Infrastructure','Access','Limits','Consequences'],'Tradition':['Participants','Origins','Ritual','Meaning','Changes over time'],'Conflict':['Causes','Participants','Stakes','Escalation','Possible resolutions']});
function types(){return [...TYPES,...world.customTypes.filter(t=>!TYPES.includes(t))];}function entry(id){return world.entries.find(e=>e.id===id);}function currentMap(){return world.maps.find(m=>m.id===selectedMap)||world.maps[0];}function signature(){return JSON.stringify(world);}function snapshot(){const {assets,...state}=world;return {...clone(state),assets:assets.map(a=>({...a}))};}function remember(){history.push(snapshot());if(history.length>40)history.shift();future=[];}function changed(){world.updated=Date.now();clearTimeout(autosaveTimer);autosaveTimer=setTimeout(writeRecovery,500);syncStatus();}function mutate(fn,redraw=true){remember();fn();changed();if(redraw)render();}function undo(){if(!history.length)return;future.push(snapshot());world=history.pop();changed();render();}function redo(){if(!future.length)return;history.push(snapshot());world=future.pop();changed();render();}function syncStatus(){const dirty=signature()!==savedSignature;$('#saveStatus').textContent=pendingSave?'Saving…':dirty?'Changes kept in local recovery · save a file to keep them':'Project file saved';$('[data-action=undo]').disabled=!history.length;$('[data-action=redo]').disabled=!future.length;}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function modal(title,body,foot=''){const d=$('#dialog');$('#dialogBody').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-action="close-dialog" aria-label="Close">×</button></div>${body}${foot?'<div class="dialog-foot">'+foot+'</div>':''}`;if(!d.open)d.showModal();}
function options(values,value){return values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');}function field(label,html,full=false){return `<label class="${full?'full':''}">${esc(label)}${html}</label>`;}function inputField(label,key,value,scope='world',full=false,type='text'){return field(label,`<input type="${type}" data-scope="${scope}" data-field="${esc(key)}" value="${esc(value)}">`,full);}function textField(label,key,value,scope='world',rows=4,full=false){return field(label,`<textarea rows="${rows}" data-scope="${scope}" data-field="${esc(key)}">${esc(value)}</textarea>`,full);}function selectField(label,key,value,values,scope='world'){return field(label,`<select data-scope="${scope}" data-field="${esc(key)}">${options(values,value)}</select>`);}function pageHead(title,description,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;}function btn(label,action,attrs='',cls=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;}function empty(msg){return `<div class="empty">${esc(msg)}</div>`;}function linksPicker(ids,scope){return `<div class="fields">${world.entries.map(e=>`<label class="check"><input type="checkbox" data-link-scope="${scope}" value="${e.id}" ${ids.includes(e.id)?'checked':''}>${esc(e.name)} <small>${esc(e.type)}</small></label>`).join('')}</div>`;}function linkChips(ids){return ids.map(id=>{const e=entry(id);return e?btn(esc(e.name),'open-entry',`data-id="${id}"`,'link-chip'):'';}).join('');}
function bodyHtml(text){return String(text||'').split('\n').map(line=>{const m=line.match(/^(#{1,3}) (.*)/);let html=esc(m?m[2]:line).replace(/\[\[([^\]]+)\]\]/g,(_,name)=>{const e=world.entries.find(x=>x.name.toLowerCase()===name.toLowerCase());return e?btn(esc(name),'open-entry',`data-id="${e.id}"`,'link-chip'):`<span class="tag" title="No matching entry">${esc(name)}</span>`;});return m?`<h${m[1].length+1}>${html}</h${m[1].length+1}>`:html;}).join('\n');}
function navigate(next){view=next;if(view==='maps'&&!selectedMap)selectedMap=world.maps[0]?.id;render();}
function render(){if(!world)return;$('#worldName').value=world.name;$('#nav').innerHTML=NAV.map(([id,icon,label])=>btn(`<span>${icon}</span><span>${label}</span>`,'navigate',`data-view="${id}"`,view===id?'active':'')).join('');const pages={home:renderHome,entries:renderEntries,writing:renderWriting,timeline:renderTimeline,maps:renderMaps,connections:renderConnections,assets:renderAssets,settings:renderSettings};$('#main').innerHTML=(pages[view]||renderHome)();syncStatus();if(view==='maps')bindMap();}
function renderHome(){const m=world.maps[0];return `<div class="hero"><div><div class="eyebrow">${esc(world.genre)} · your world, connected</div><h1>${esc(world.name)}</h1><p>${esc(world.description||'Begin with a person, a place or a question. The rest can grow around it.')}</p><div class="actions">${btn('＋ Create an entry','new-entry','','accent')}${btn('Explore the map','navigate','data-view="maps"')}</div><div class="stats"><div><strong>${world.entries.length}</strong><small>WORLD ENTRIES</small></div><div><strong>${world.documents.length}</strong><small>DOCUMENTS</small></div><div><strong>${world.maps.length}</strong><small>MAPS</small></div></div></div><div class="hero-map">${m?mapSVG(m,{exporting:true}):empty('A map is waiting to happen.')}</div></div><div class="grid"><div class="card"><div class="eyebrow">A useful beginning</div><h2>Your world’s premise</h2><p>${esc(world.premise||'What makes this world worth exploring?')}</p>${btn('Edit the foundations','navigate','data-view="settings"')}</div><div class="card"><div class="eyebrow">Continue exploring</div><h2>Recently touched</h2>${[...world.entries].sort((a,b)=>b.updated-a.updated).slice(0,4).map(e=>`<p>${btn(esc(e.name),'open-entry',`data-id="${e.id}"`,'link-chip')} <small>${esc(e.type)}</small></p>`).join('')||'<p>No entries yet.</p>'}</div><div class="card"><div class="eyebrow">Keep the threads together</div><h2>World checks</h2>${worldChecks().slice(0,4).map(s=>`<p>• ${esc(s)}</p>`).join('')||'<p>Your links are connected. Keep building.</p>'}${btn('See connections','navigate','data-view="connections"')}</div></div>`;}
function renderEntries(){let e=entry(selectedEntry);const filtered=world.entries.filter(x=>(!folderFilter||folderContains(x.folderId,folderFilter))&&(entryFilter==='All'||x.type===entryFilter)&&(!listQuery||(x.name+' '+x.summary+' '+x.tags.join(' ')).toLowerCase().includes(listQuery.toLowerCase())));if(!e&&filtered.length){e=filtered[0];selectedEntry=e.id;}return pageHead('World library','People, places and ideas. Give them somewhere to belong.',btn('＋ New entry','new-entry','','accent'))+`<div class="workspace"><div class="list-panel"><select id="entryFilter">${options(['All',...types()],entryFilter)}</select><input id="entrySearch" placeholder="Filter entries…" value="${esc(listQuery)}">${filtered.map(x=>btn(`<strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${esc(x.status)}</small>`,'open-entry',`data-id="${x.id}"`,'list-item '+(e?.id===x.id?'active':''))).join('')||empty('No matching entries.')}</div>${e?renderEntryEditor(e):empty('Create your first world entry.')}</div>`;}
function renderEntryEditor(e){const related=world.relations.filter(r=>r.from===e.id||r.to===e.id),backlinks=world.entries.filter(x=>x.id!==e.id&&x.body.includes('[['+e.name+']]')),docs=world.documents.filter(d=>d.links.includes(e.id)),pins=world.maps.flatMap(m=>m.objects.filter(o=>o.entryId===e.id).map(o=>m));let content='';if(entryTab==='write')content=`<div class="fields">${selectField('Entry type','type',e.type,types(),'entry')}${selectField('State','status',e.status,['Draft','Canon','Alternative'],'entry')}${inputField('Tags · comma separated','tags',e.tags.join(', '),'entry',true)}${textField('A short description','summary',e.summary,'entry',3,true)}</div>${textField('Lore · headings with # · link entries with [[Name]]','body',e.body,'entry',13)}<div class="divider"></div><h3>Reading view</h3><div class="body-preview">${bodyHtml(e.body)||'<span class="muted">Your writing appears here.</span>'}</div>`;if(entryTab==='details')content=`<p class="muted">These prompts are yours to change. Keep the useful ones.</p><div class="fields">${Object.entries(e.fields).map(([k,v])=>textField(k,k,v,'entry-custom',3)).join('')}</div>${btn('＋ Add a custom field','custom-field')}<hr class="divider"><h3>Reference images</h3><div class="fields">${world.assets.map(a=>`<label class="check"><input type="checkbox" data-entry-asset="${a.id}" ${(e.references||[]).includes(a.id)?'checked':''}>${esc(a.name)}</label>`).join('')||'<p class="muted">Import images in Assets to attach them here.</p>'}</div><div class="grid">${world.assets.filter(a=>(e.references||[]).includes(a.id)).map(a=>`<div class="asset-thumb"><img src="${a.src}" alt="${esc(a.name)}"></div>`).join('')}</div><hr class="divider">${textField('Private notes & secrets · omitted from public reference exports','secret',e.secret,'entry',5)}`;if(entryTab==='connections')content=`<h3>Relationships</h3>${related.map(r=>`<div class="row">${linkChips([r.from])}<span>${esc(r.label)}</span>${linkChips([r.to])}${btn('×','delete-relation',`data-id="${r.id}"`)}</div>`).join('')||'<p class="muted">Nothing connected yet.</p>'}${btn('＋ Add relationship','new-relation',`data-id="${e.id}"`)}<hr class="divider"><h3>Linked from</h3>${linkChips(backlinks.map(x=>x.id))||'<p class="muted">Other entries can reference this one using [[Name]].</p>'}<h3 style="margin-top:20px">In your writing</h3>${docs.map(d=>btn(esc(d.name),'open-doc',`data-id="${d.id}"`,'link-chip')).join('')||'<p class="muted">No linked documents.</p>'}<h3 style="margin-top:20px">On the map</h3>${pins.map(m=>btn(esc(m.name),'open-map',`data-id="${m.id}"`,'link-chip')).join('')||'<p class="muted">Select a map marker and link it to this entry.</p>'}`;return `<div class="editor"><input class="entry-title" data-scope="entry" data-field="name" value="${esc(e.name)}" aria-label="Entry name"><div class="tabs">${['write','details','connections'].map(t=>btn(t[0].toUpperCase()+t.slice(1),'entry-tab',`data-tab="${t}"`,entryTab===t?'active':'')).join('')}</div>${content}<hr class="divider"><div class="actions">${btn('Duplicate','duplicate-entry',`data-id="${e.id}"`)}${btn('Export entry','export-entry',`data-id="${e.id}"`)}${btn('Delete entry','delete-entry',`data-id="${e.id}"`,'danger')}</div></div>`;}
function renderWriting(){let d=world.documents.find(x=>x.id===selectedDoc)||world.documents[0];if(d)selectedDoc=d.id;const docs=[...world.documents].sort((a,b)=>a.order-b.order);return pageHead('Writing desk','Reference notes, scenes and stories, connected to your world.',btn('＋ New document','new-doc','','accent')+btn(docView==='board'?'Writing view':'Scene board','toggle-board'))+(docView==='board'?`<div class="board">${['Draft','In progress','Complete'].map(status=>`<div class="board-column"><h3>${status}</h3>${docs.filter(x=>x.status===status).map(x=>`<div class="card clickable" data-action="open-doc" data-id="${x.id}"><small>${esc(x.kind)}</small><h3>${esc(x.name)}</h3><p>${esc(x.goal||x.body.slice(0,100))}</p>${linkChips(x.links)}</div>`).join('')}</div>`).join('')}</div>`:`<div class="workspace"><div class="list-panel">${docs.map(x=>btn(`<strong>${esc(x.name)}</strong><small>${esc(x.kind)} · ${wordCount(x.body)} words</small>`,'open-doc',`data-id="${x.id}"`,'list-item '+(x.id===d?.id?'active':''))).join('')||empty('No documents yet.')}</div>${d?`<div class="editor"><input class="entry-title" data-scope="doc" data-field="name" value="${esc(d.name)}" aria-label="Document name"><div class="fields">${selectField('Document type','kind',d.kind,['Reference','Outline','Chapter','Scene','Research'],'doc')}${selectField('Progress','status',d.status,['Draft','In progress','Complete'],'doc')}${inputField('Goal / purpose','goal',d.goal||'','doc')}${inputField('Conflict / question','conflict',d.conflict||'','doc')}${inputField('Order','order',d.order,'doc',false,'number')}</div>${textField('Write · # headings and [[world links]] supported','body',d.body,'doc',17)}<small>${wordCount(d.body)} words</small><hr class="divider"><details><summary>Linked world entries</summary>${linksPicker(d.links,'doc')}</details><hr class="divider"><div class="actions">${btn('Reading view','read-doc')}${btn('Export Markdown','export-doc')}${btn('Delete document','delete-doc',`data-id="${d.id}"`,'danger')}</div></div>`:empty('Start a reference document or a scene.')}</div>`);}
function wordCount(s){return s.trim().split(/\s+/).filter(Boolean).length;}
function renderTimeline(){const events=[...world.events].sort((a,b)=>a.year-b.year);return pageHead('Timeline','History and story beats. Dates use your world’s own year numbering.',btn('＋ New event','new-event','','accent'))+(events.length?`<div class="timeline">${events.map(e=>`<div class="card event"><div class="row" style="justify-content:space-between"><div><div class="event-year">${esc(world.calendar)} ${e.year}${e.date?' · '+esc(e.date):''} · ${esc(e.visibility)}</div><h3>${esc(e.name)}</h3></div>${btn('Edit','edit-event',`data-id="${e.id}"`)}</div><div class="body-preview">${bodyHtml(e.body)}</div><div>${linkChips(e.links)}</div></div>`).join('')}</div>`:empty('Add a founding, a discovery or the day everything changed.'));}
function worldChecks(){const out=[],names=new Set();for(const e of world.entries){if(names.has(e.name.toLowerCase()))out.push('Duplicate name: '+e.name);names.add(e.name.toLowerCase());for(const match of e.body.matchAll(/\[\[([^\]]+)\]\]/g))if(!world.entries.some(x=>x.name.toLowerCase()===match[1].toLowerCase()))out.push(e.name+' references a missing entry: '+match[1]);}for(const d of world.documents)for(const match of d.body.matchAll(/\[\[([^\]]+)\]\]/g))if(!world.entries.some(x=>x.name.toLowerCase()===match[1].toLowerCase()))out.push(d.name+' references a missing entry: '+match[1]);for(const m of world.maps)for(const o of m.objects)if(o.entryId&&!entry(o.entryId))out.push(m.name+' contains an unlinked marker.');return out;}
function renderConnections(){const entries=world.entries.slice(0,60),width=1000,height=520,pos=new Map(entries.map((e,i)=>[e.id,{x:width/2+Math.cos(i/entries.length*6.28)*350,y:height/2+Math.sin(i/entries.length*6.28)*195}]));return pageHead('Connections','See how your world belongs together. Solid lines show named relationships.',btn('＋ Relationship','new-relation','','accent'))+`<svg class="relationship-svg" viewBox="0 0 ${width} ${height}">${world.relations.map(r=>{const a=pos.get(r.from),b=pos.get(r.to);return a&&b?`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#b8c5b0"/><text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2}" fill="#69766d" font-size="10" text-anchor="middle">${esc(r.label)}</text>`:'';}).join('')}${entries.map(e=>{const p=pos.get(e.id);return `<g data-action="open-entry" data-id="${e.id}" style="cursor:pointer"><circle cx="${p.x}" cy="${p.y}" r="20" fill="${e.type==='Character'?'#b68352':e.type==='Place'?'#527b6a':'#858e6a'}"/><text x="${p.x}" y="${p.y+4}" fill="white" text-anchor="middle" font-size="13">${esc(e.type[0])}</text><text x="${p.x}" y="${p.y+36}" text-anchor="middle" fill="#243834" font-size="12">${esc(e.name.slice(0,28))}</text></g>`;}).join('')}</svg>${world.entries.length>60?'<p class="muted">The diagram shows the first 60 entries. All relationships remain available below.</p>':''}<div class="split" style="margin-top:20px"><div class="card"><h3>Relationships</h3>${world.relations.map(r=>`<div class="row">${linkChips([r.from])}<small>${esc(r.label)}</small>${linkChips([r.to])}${btn('×','delete-relation',`data-id="${r.id}"`)}</div>`).join('')||'<p class="muted">Connect people, places and ideas.</p>'}</div><div class="card"><h3>Reference checks</h3>${worldChecks().map(x=>`<p>${esc(x)}</p>`).join('')||'<p>All named references resolve. These checks find missing links, rather than judging your story’s logic.</p>'}</div></div>`;}
function renderAssets(){return pageHead('Assets','Reference images and map symbols, stored with your project.',btn('＋ Import images','import-assets','','accent'))+`<div class="notice" style="margin-bottom:18px">PNG, JPEG, WebP and SVG imports are normalised to PNG for portable projects and reliable map exports. Images are limited to a 4096 px longest edge.</div>`+(world.assets.length?`<div class="grid">${world.assets.map(a=>`<div class="card"><div class="asset-thumb"><img src="${esc(a.src)}" alt="${esc(a.name)}"></div><h3>${esc(a.name)}</h3><small>${a.width} × ${a.height} px</small><div class="actions" style="margin-top:12px">${btn('Place on map','place-asset',`data-id="${a.id}"`)}${btn('Use as map background','background-asset',`data-id="${a.id}"`)}${btn('Remove','delete-asset',`data-id="${a.id}"`,'danger')}</div></div>`).join('')}</div>`:empty('Bring in your sketches, references or custom map symbols.'));}
function renderSettings(){return pageHead('World foundations','Keep the big questions nearby. Change anything as your world grows.')+`<div class="editor"><div class="fields">${inputField('World name','name',world.name)}${inputField('Genre / style','genre',world.genre)}${textField('Description','description',world.description,'world',4,true)}${textField('Premise / central question','premise',world.premise,'world',4,true)}${inputField('Tone','tone',world.tone)}${inputField('Year label','calendar',world.calendar)}${textField('Working notes','notes',world.notes,'world',6,true)}</div><hr class="divider"><h3>Your entry categories</h3><p>${types().map(t=>'<span class="tag">'+esc(t)+'</span>').join('')}</p>${btn('＋ Add category','custom-type')}<hr class="divider"><h3>Local recovery</h3><p class="muted">The last working world is recovered on this device. Save a .jagoworld file for backups, moving computers or sharing your editable world.</p>${btn('Download project backup','save','','accent')}</div>`;}
Object.assign(GENRES,{steampunk:{name:'Steampunk',tag:'Industry, invention and competing ambitions.',world:'The Brass Estuary',kind:'Steampunk',entry:'The Clockmaker’s Heir',place:'Copper Quay',faction:'The Engine Society',theme:'parchment',summary:'An industrial port runs on engines nobody remembers how to build.',magic:'Who controls energy and invention?',story:'The stopped engine'},postapoc:{name:'Post-apocalyptic',tag:'Survival, memory and rebuilding.',world:'After the Green Rain',kind:'Post-apocalyptic',entry:'The Seed Courier',place:'The Glass Gardens',faction:'The Salvage Union',theme:'atlas',summary:'Scattered communities grow new lives inside the remains of an old world.',magic:'What survived, what was lost, and what is returning?',story:'The last delivery'},cyberpunk:{name:'Cyberpunk',tag:'Networks, identity and uneven power.',world:'Neon Lowlands',kind:'Cyberpunk',entry:'The Memory Broker',place:'Undergrid',faction:'The Open Circuit',theme:'blueprint',summary:'A city trades memories as its streets disappear beneath rising water.',magic:'Who owns information and the infrastructure?',story:'A borrowed memory'},cozy:{name:'Cozy / pastoral',tag:'Small communities and meaningful everyday stakes.',world:'Moss & Morning',kind:'Cozy fantasy',entry:'The Travelling Baker',place:'Willowcross',faction:'The Garden Circle',theme:'rose',summary:'A village prepares for a festival that has not been held in a hundred years.',magic:'What gives ordinary life its small wonders?',story:'The missing recipe'},mythic:{name:'Mythic',tag:'Origins, symbols and competing legends.',world:'The Seven Dawns',kind:'Mythic',entry:'The Keeper of Names',place:'The First Shore',faction:'The Witnesses',theme:'ink',summary:'Each dawn tells a different story of how the world began.',magic:'Which myths shape reality, and which merely explain it?',story:'The eighth dawn'}});
function mapTheme(m){const base=THEMES[m.theme]||THEMES.parchment,climate=m.terrain?.climate,adjust=['parchment','atlas','rose'].includes(m.theme)?climate==='Arid'?{land:'#e8cf9e',forest:'#a0915a'}:climate==='Polar'?{land:'#ecede4',forest:'#849e9c'}:climate==='Tropical'?{forest:'#477b51'}:{}:{};return {...base,...adjust,...(m.palette||{})};}
function ptsString(points){return points.map(p=>p.map(n=>Number(n).toFixed(2)).join(',')).join(' ');}
function mountainSVG(x,y,s,color){return `<path d="M${x-s*.7},${y+s*.5} L${x},${y-s*.6} L${x+s*.7},${y+s*.5} M${x-s*.25},${y-s*.2} L${x},${y-s*.03} L${x+s*.19},${y-s*.26}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linejoin="round"/>`;}
function forestSVG(x,y,s,color){return `<path d="M${x},${y-s*.7} L${x-s*.4},${y} L${x-s*.17},${y} L${x-s*.5},${y+s*.35} L${x+s*.5},${y+s*.35} L${x+s*.17},${y} L${x+s*.4},${y} Z M${x},${y+s*.35} L${x},${y+s*.7}" fill="${color}" fill-opacity=".35" stroke="${color}" stroke-width="1.2"/>`;}
function objectSVG(o,m,exporting=false){const t=mapTheme(m),color=o.color||t.ink,layer=o.layer||'symbols';if(!mapShow[layer]&&!exporting)return '';const attrs=`data-object="${o.id}"`,opacity=o.opacity??1;let art='';if(['region','land'].includes(o.kind))art=`<polygon ${attrs} points="${ptsString(o.points)}" fill="${color}" fill-opacity="${o.kind==='land'?1:.24}" stroke="${o.kind==='land'?t.ink:color}" stroke-width="${o.stroke||2}"/>`;else if(['route','river'].includes(o.kind))art=`<polyline ${attrs} points="${ptsString(o.points)}" fill="none" stroke="${color}" stroke-width="${o.stroke||3}" stroke-dasharray="${o.kind==='route'?'8 6':''}" stroke-linecap="round" stroke-linejoin="round"/>`;else if(o.kind==='image'){const a=world.assets.find(a=>a.id===o.assetId);if(a)art=`<image ${attrs} href="${esc(a.src)}" x="${o.x-o.size/2}" y="${o.y-o.size*a.height/a.width/2}" width="${o.size}" height="${o.size*a.height/a.width}" transform="rotate(${o.rotation||0} ${o.x} ${o.y})"/>`;}else if(o.kind==='label')art=`<text ${attrs} x="${o.x}" y="${o.y}" font-family="${o.font==='sans'?'Segoe UI,Arial,sans-serif':'Georgia,serif'}" font-size="${o.size}" fill="${color}" text-anchor="middle" transform="rotate(${o.rotation||0} ${o.x} ${o.y})">${esc(o.label)}</text>`;else{const x=o.x,y=o.y,s=o.size,sy=o.symbol;let symbol=sy==='mountain'?mountainSVG(0,0,s,color):sy==='forest'?forestSVG(0,0,s,color):sy==='town'?`<path d="M${-s*.35},${s*.3}V${-s*.1}L0,${-s*.4}L${s*.35},${-s*.1}V${s*.3}Z M${-s*.08},${s*.3}V0H${s*.08}V${s*.3}" fill="${t.land}" stroke="${color}" stroke-width="2"/>`:sy==='capital'||sy==='ruin'?`<path d="M${-s*.4},${s*.4}V${-s*.3}H${-s*.22}V${-s*.1}H${-s*.1}V${-s*.3}H${s*.1}V${-s*.1}H${s*.22}V${-s*.3}H${s*.4}V${s*.4}Z" fill="${t.land}" stroke="${color}" stroke-width="2"/>`:sy==='port'?`<path d="M0,${-s*.3}V${s*.4}M${-s*.4},0Q${-s*.35},${s*.5}0,${s*.4}Q${s*.35},${s*.5}${s*.4},0M${-s*.2},${-s*.1}H${s*.2}" stroke="${color}" fill="none" stroke-width="2"/><circle cy="${-s*.4}" r="${s*.12}" fill="none" stroke="${color}" stroke-width="2"/>`:`<text text-anchor="middle" dominant-baseline="central" font-family="Segoe UI Symbol,serif" font-size="${s}" fill="${color}">${esc(SYMBOLS[sy]?.glyph||'✦')}</text>`;art=`<g ${attrs} transform="translate(${x} ${y}) rotate(${o.rotation||0})">${symbol}<circle r="${s*.7}" fill="transparent"/></g>`;if(o.label&&(mapShow.labels||exporting))art+=`<text ${attrs} x="${x}" y="${y+s*.95}" text-anchor="middle" font-family="Georgia,serif" font-size="${o.labelSize||20}" fill="${color}" paint-order="stroke" stroke="${t.land}" stroke-width="3">${esc(o.label)}</text>`;}if(o.points&&o.label&&(mapShow.labels||exporting)){const middle=o.kind==='route'||o.kind==='river'?o.points[Math.floor(o.points.length/2)]:o.points.reduce((a,p)=>[a[0]+p[0]/o.points.length,a[1]+p[1]/o.points.length],[0,0]);art+=`<text ${attrs} x="${middle[0]}" y="${middle[1]}" text-anchor="middle" font-family="Georgia,serif" font-size="${o.labelSize||24}" fill="${t.ink}" paint-order="stroke" stroke="${t.land}" stroke-width="3">${esc(o.label)}</text>`;}return `<g opacity="${opacity}">${art}</g>`;}
function mapSVG(m,{exporting=false,transparent=false}={}){const t=mapTheme(m),lands=m.terrain?.lands||[],vb=!exporting&&mapViewport?`${mapViewport.x} ${mapViewport.y} ${mapViewport.w} ${mapViewport.h}`:`0 0 ${m.width} ${m.height}`,terrainVisible=exporting||mapShow.terrain,bg=m.background&&world.assets.find(a=>a.id===m.background);let html=`<svg xmlns="http://www.w3.org/2000/svg" width="${m.width}" height="${m.height}" viewBox="${vb}" role="img" aria-label="${esc(m.name)}"><defs><clipPath id="landclip-${m.id}">${lands.map(p=>`<polygon points="${ptsString(p)}"/>`).join('')}</clipPath><pattern id="grid-${m.id}" width="100" height="100" patternUnits="userSpaceOnUse"><path d="M100 0H0V100" stroke="${t.ink}" stroke-opacity=".15" fill="none"/></pattern></defs>${transparent?'':`<rect width="${m.width}" height="${m.height}" fill="${t.sea}"/>`}`;if(bg)html+=`<image data-map-background="${m.background}" href="${esc(bg.src)}" width="${m.width}" height="${m.height}" preserveAspectRatio="xMidYMid meet"/>`;if(terrainVisible){html+=lands.map(p=>`<polygon points="${ptsString(p)}" fill="${t.land}" stroke="${t.ink}" stroke-width="2"/>`).join('');html+=`<g clip-path="url(#landclip-${m.id})">${(m.terrain?.decor||[]).map(d=>d.kind==='forest'?forestSVG(d.x,d.y,d.size,t.forest):mountainSVG(d.x,d.y,d.size,t.mountain)).join('')}${(m.terrain?.rivers||[]).map(p=>`<polyline points="${ptsString(p)}" fill="none" stroke="${t.sea}" stroke-width="4" stroke-linecap="round"/>`).join('')}</g>`;}
for(const layer of ['terrain','regions','routes','symbols','labels'])for(const o of m.objects.filter(o=>(o.layer||'symbols')===layer))if(exporting||mapShow[layer])html+=objectSVG(o,m,exporting);
if(!exporting&&mapShow.grid)html+=`<rect width="${m.width}" height="${m.height}" fill="url(#grid-${m.id})" pointer-events="none"/>`;if(!exporting&&mapShow.guides)html+=`<path d="M${m.width/2},0V${m.height}M0,${m.height/2}H${m.width}" stroke="${t.ink}" stroke-dasharray="8 8" opacity=".4" pointer-events="none"/>`;
if(m.compass)html+=`<g transform="translate(${m.width-80} 85)" fill="${t.ink}"><path d="M0 -35L10 0L0 -8L-10 0Z"/><text y="-45" text-anchor="middle" font-family="Georgia" font-size="20">N</text></g>`;
if(m.scale)html+=`<g transform="translate(50 ${m.height-45})" stroke="${t.ink}" fill="${t.ink}"><path d="M0 -8V0H200V-8M100 0V-8" fill="none" stroke-width="2"/><text x="100" y="22" stroke="none" text-anchor="middle" font-size="16" font-family="Georgia">${esc(m.scaleLabel||'100 leagues')}</text></g>`;
if(!exporting){const o=m.objects.find(o=>o.id===mapSelection);if(o){if(o.points)html+=o.points.map((p,i)=>`<circle data-node="${i}" data-object="${o.id}" cx="${p[0]}" cy="${p[1]}" r="${5*(mapViewport?.w||m.width)/m.width}" fill="#fff" stroke="#b56e35" stroke-width="2"/>`).join('');else html+=`<circle cx="${o.x}" cy="${o.y}" r="${o.size*.8}" fill="none" stroke="#c47937" stroke-width="2" stroke-dasharray="5 5" pointer-events="none"/>`;}if(mapDraft.length)html+=`<polyline points="${ptsString(mapDraft)}" stroke="#c47937" fill="${['land','region'].includes(mapTool)?'#c4793722':'none'}" stroke-width="3" pointer-events="none"/>`;}return html+'</svg>';}
function generateAdvanced(m,settings){const s={style:'islands',count:3,coverage:65,roughness:50,mountains:45,forests:55,rivers:5,climate:'Temperate',seed:'world-1',...settings},rand=rng(s.seed),lands=[],decor=[],rivers=[];const n=s.style==='continent'?1:clamp(+s.count,1,12),cols=Math.max(1,Math.round(Math.sqrt(n*m.width/m.height))),rows=Math.ceil(n/cols),cellW=m.width/cols,cellH=m.height/rows;for(let k=0;k<n;k++){const cx=n===1?m.width/2:cellW*(k%cols+.5)+(rand()-.5)*cellW*.16,cy=n===1?m.height/2:cellH*(Math.floor(k/cols)+.5)+(rand()-.5)*cellH*.16,cov=(.18+Number(s.coverage)/100*.25)*.9*(s.style==='archipelago'?.78:1),rx=(n===1?m.width:cellW)*cov,ry=(n===1?m.height:cellH)*cov,phase=rand()*6.28,rough=Number(s.roughness)/100;const points=[];const detail=clamp(Number(s.coastDetail??50),0,100),samples=Math.round(80+detail*4);for(let i=0;i<samples;i++){const a=i/samples*Math.PI*2,r=coastRadius(a,phase,rough,s);points.push([clamp(cx+Math.cos(a)*rx*r,10,m.width-10),clamp(cy+Math.sin(a)*ry*r,10,m.height-10)]);}lands.push(points);const count=Math.round((rx*ry)/(m.width*m.height)*800);for(let i=0;i<count;i++){const a=rand()*6.28,r=Math.sqrt(rand())*.9,x=cx+Math.cos(a)*rx*r,y=cy+Math.sin(a)*ry*r;let kind=rand()<Number(s.mountains)/100?'mountain':'forest';if(kind==='forest'&&(rand()>Math.min(1,Number(s.forests)/100*(s.climate==='Tropical'?1.4:1))||s.climate==='Arid'||s.climate==='Polar'))continue;decor.push({x,y,kind,size:10+rand()*17});}for(let j=0;j<Math.floor(Number(s.rivers)/n)+(k<Number(s.rivers)%n?1:0);j++){let x=cx+(rand()-.5)*rx*.5,y=cy+(rand()-.5)*ry*.4,a=rand()*6.28;const path=[[x,y]];for(let i=0;i<18;i++){a+=(rand()-.5)*.65;x+=Math.cos(a)*rx/12;y+=Math.sin(a)*ry/12;path.push([x,y]);}rivers.push(path);}}return {...s,riverCount:s.rivers,lands,decor,rivers};}
function renderMaps(){const m=currentMap();if(m)selectedMap=m.id;return pageHead('Map studio','Make a place worth exploring. Draw, generate, annotate and connect.',`<select id="mapSelect" aria-label="Select map">${world.maps.map(x=>`<option value="${x.id}" ${x.id===m?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`+btn('＋ New map','new-map')+btn('Generate map','generate-map','','accent')+btn('Export map','export-map'))+(m?`<div class="map-layout"><div class="map-wrap"><div class="map-toolbar">${[['select','↖','Select / move'],['pan','✥','Pan'],['symbol','⌂','Place symbol'],['label','T','Add label'],['land','◒','Draw land'],['region','⬡','Draw region'],['route','┄','Draw route'],['river','≈','Draw river'],['mountain','▲','Paint mountains'],['forest','♠','Paint forests'],['erase','⌫','Erase object']].map(([id,icon,title])=>btn(icon,'map-tool',`data-tool="${id}" title="${title}" aria-label="${title}"`,'map-tool '+(mapTool===id?'active':''))).join('')}${mapDraft.length?btn('Finish shape','finish-shape'):''}</div><div class="map-stage" id="mapStage">${mapSVG(m)}</div><div class="map-footer"><span>${esc(m.name)} · ${m.width} × ${m.height} world units · ${mapTool}</span><div class="actions">${btn('−','map-zoom','data-factor="1.25"')}${btn('Fit','map-fit')}${btn('＋','map-zoom','data-factor="0.8"')}</div></div></div><div class="map-inspector" id="mapInspector">${renderMapInspector(m)}</div></div>`:empty('Create your first map, or generate geography from a seed.'));}
function renderMapInspector(m){const o=m.objects.find(o=>o.id===mapSelection),t=mapTheme(m);let html=`<h3>Map appearance</h3>${inputField('Map name','name',m.name,'map')}${field('Style theme',`<select data-scope="map" data-field="theme">${Object.entries(THEMES).map(([k,v])=>`<option value="${k}" ${m.theme===k?'selected':''}>${v.name}</option>`).join('')}</select>`)}<div class="swatches">${[t.sea,t.land,t.forest,t.mountain,t.ink].map(c=>`<span style="background:${c}"></span>`).join('')}</div>${btn('Customise palette','map-palette')}<hr class="divider">`;if(mapTool==='symbol')html+=`<h3>Symbols</h3><div class="symbol-grid">${Object.entries(SYMBOLS).map(([id,s])=>btn(s.glyph,'choose-symbol',`data-symbol="${id}" title="${s.name}"`,mapSymbol===id?'active':'')).join('')}</div><p class="map-tip">Click the map to place a ${SYMBOLS[mapSymbol].name.toLowerCase()}. Select it to name it or link it to lore.</p>`;if(['land','region','route','river'].includes(mapTool))html+='<p class="map-tip">Click to add points. Use Finish shape or press Enter to finish. Escape cancels. Select a shape afterwards to move it or drag its point handles.</p>';if(['mountain','forest'].includes(mapTool))html+=field('Brush size',`<input type="range" data-brush="size" min="8" max="120" value="${brushSize}">`)+field('Brush spacing',`<input type="range" data-brush="spacing" min="8" max="150" value="${brushSpacing}">`)+'<p class="map-tip">Drag to paint terrain symbols. They are editable objects, separate from generated terrain.</p>';if(o)html+=`<h3>Selected ${esc(o.kind)}</h3>${inputField('Label','label',o.label||'','object')}${!o.points?inputField('Size','size',o.size,'object',false,'number')+inputField('Rotation °','rotation',o.rotation||0,'object',false,'number'):inputField('Line width','stroke',o.stroke||2,'object',false,'number')}${inputField('Colour','color',o.color||t.ink,'object',false,'color')}${inputField('Opacity · 0 to 1','opacity',o.opacity??1,'object',false,'number')}${field('Linked world entry',`<select data-scope="object" data-field="entryId"><option value="">No link</option>${world.entries.map(e=>`<option value="${e.id}" ${o.entryId===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)}${o.entryId?btn('Open linked lore','open-entry',`data-id="${o.entryId}"`):btn('Create place from marker','marker-entry')}${btn('Duplicate','duplicate-object')}${btn('Delete','delete-object','','danger')}<hr class="divider">`;else html+='<p class="map-tip">Select an object to resize, rotate, recolour or connect it to your world.</p>';html+=`<h3>View layers</h3>${Object.keys(mapShow).map(k=>`<label class="check"><input type="checkbox" data-map-show="${k}" ${mapShow[k]?'checked':''}>${k[0].toUpperCase()+k.slice(1)}</label>`).join('')}<p class="map-tip">View toggles are editing aids. Map exports include all artwork, without the editing grid or guides.</p><hr class="divider"><h3>Map decorations</h3><label class="check"><input type="checkbox" data-scope="map" data-field="compass" ${m.compass?'checked':''}>North arrow</label><label class="check"><input type="checkbox" data-scope="map" data-field="scale" ${m.scale?'checked':''}>Scale bar</label>${m.scale?inputField('Scale label · your own units','scaleLabel',m.scaleLabel||'100 leagues','map'):''}<hr class="divider"><h3>Objects · ${m.objects.length}</h3><div class="layer-list">${[...m.objects].reverse().slice(0,80).map(o=>btn(`<span>${esc(o.label||SYMBOLS[o.symbol]?.name||o.kind)}</span><small>${esc(o.layer)}</small>`,'select-object',`data-id="${o.id}"`,mapSelection===o.id?'active':'')).join('')}</div><hr class="divider">${btn('Edit coastlines','unlock-coasts')}${m.background?btn('Remove background','remove-background'):''}${btn('Map notes & dimensions','map-properties')}${btn('Delete map','delete-map',`data-id="${m.id}"`,'danger')}`;return html;}
function refreshMap(){const stage=$('#mapStage');if(stage){stage.innerHTML=mapSVG(currentMap());$('#mapInspector').innerHTML=renderMapInspector(currentMap());}}
function mapPoint(event){const svg=$('#mapStage svg'),point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());return [p.x,p.y];}
function addMapObject(kind,p){const m=currentMap(),t=mapTheme(m),o={id:uid(),kind:kind==='mountain'||kind==='forest'?'symbol':kind,x:p[0],y:p[1],size:kind==='label'?28:['mountain','forest'].includes(kind)?brushSize:30,rotation:0,color:kind==='forest'?t.forest:kind==='mountain'?t.mountain:t.ink,label:kind==='label'?'New label':'',symbol:kind==='symbol'?mapSymbol:kind,entryId:'',layer:kind==='label'?'labels':kind==='mountain'||kind==='forest'?'terrain':'symbols'};m.objects.push(o);mapSelection=o.id;return o;}
function finishShape(){if(mapDraft.length<(['land','region'].includes(mapTool)?3:2)){toast('Add more points to finish this shape.');return;}mutate(()=>{const m=currentMap(),t=mapTheme(m),o={id:uid(),kind:mapTool,points:clone(mapDraft),color:mapTool==='land'?t.land:mapTool==='river'?t.sea:mapTool==='route'?t.route:t.forest,stroke:mapTool==='river'?4:2,label:'',layer:mapTool==='land'?'terrain':mapTool==='region'?'regions':'routes'};m.objects.push(o);mapSelection=o.id;mapDraft=[];mapTool='select';});}
function bindMap(){const stage=$('#mapStage');let drag=null;stage.onpointerdown=e=>{if(e.button!==0)return;const p=mapPoint(e),target=e.target.closest('[data-object]'),o=currentMap().objects.find(o=>o.id===target?.dataset.object);if(mapTool==='pan'||e.altKey){const m=currentMap();if(!mapViewport)mapViewport={x:0,y:0,w:m.width,h:m.height};drag={mode:'pan',start:p,base:clone(mapViewport)};}else if(['land','region','route','river'].includes(mapTool)){mapDraft.push(p);render();return;}else if(mapTool==='erase'){if(o)mutate(()=>currentMap().objects=currentMap().objects.filter(x=>x.id!==o.id));return;}else if(['symbol','label'].includes(mapTool)){mutate(()=>addMapObject(mapTool,p));return;}else if(['mountain','forest'].includes(mapTool)){remember();addMapObject(mapTool,p);drag={mode:'paint',last:p};refreshMap();}else if(o){mapSelection=o.id;remember();drag={mode:'move',start:p,base:clone(o),o,node:e.target.dataset.node!==undefined?+e.target.dataset.node:null};refreshMap();}else{mapSelection=null;refreshMap();return;}stage.setPointerCapture(e.pointerId);};stage.onpointermove=e=>{if(!drag)return;const p=mapPoint(e);if(drag.mode==='pan'){const dx=p[0]-drag.start[0],dy=p[1]-drag.start[1];mapViewport.x-=dx;mapViewport.y-=dy;stage.innerHTML=mapSVG(currentMap());}else if(drag.mode==='paint'){if(Math.hypot(p[0]-drag.last[0],p[1]-drag.last[1])>brushSpacing){addMapObject(mapTool,p);drag.last=p;stage.innerHTML=mapSVG(currentMap());}}else{const dx=p[0]-drag.start[0],dy=p[1]-drag.start[1];if(drag.o.points){if(drag.node!==null)drag.o.points[drag.node]=p;else drag.o.points=drag.base.points.map(q=>[q[0]+dx,q[1]+dy]);}else{drag.o.x=drag.base.x+dx;drag.o.y=drag.base.y+dy;}stage.innerHTML=mapSVG(currentMap());}};const done=()=>{if(drag&&drag.mode!=='pan')changed();drag=null;refreshMap();};stage.onpointerup=done;stage.onpointercancel=done;stage.onwheel=e=>{e.preventDefault();zoomMap(e.deltaY>0?1.15:.87);};}
function zoomMap(factor){const m=currentMap();if(!mapViewport)mapViewport={x:0,y:0,w:m.width,h:m.height};const v=mapViewport,nw=clamp(v.w*factor,m.width*.08,m.width*4),nh=nw*m.height/m.width;v.x+=(v.w-nw)/2;v.y+=(v.h-nh)/2;v.w=nw;v.h=nh;refreshMap();}
function generationDialog(){if(!currentMap()){mutate(()=>{const m=makeMap();world.maps.push(m);selectedMap=m.id;});view='maps';}const m=currentMap(),s=m.terrain||{};modal('Generate geography',`<p class="muted">A repeatable seed creates the same geography. Regenerating replaces generated terrain and keeps your placed objects.</p><div class="fields">${field('Seed','<input id="genSeed" value="'+esc(s.seed||'new-world-1')+'">')}${field('Land arrangement','<select id="genStyle">'+options(['islands','continent','archipelago'],s.style||'islands')+'</select>')}${field('Land masses · 1–12','<input id="genCount" type="number" min="1" max="12" value="'+(s.count||3)+'">')}${field('Climate','<select id="genClimate">'+options(['Temperate','Tropical','Arid','Polar'],s.climate||'Temperate')+'</select>')}${[['coverage','Land coverage',65],['roughness','Coastline roughness',50],['mountains','Mountain density',45],['forests','Forest density',55],['rivers','River count',5]].map(([k,n,v])=>field(n,`<input id="gen-${k}" type="range" min="0" max="${k==='rivers'?20:100}" value="${(k==='rivers'?s.riverCount:s[k])??v}" oninput="this.nextElementSibling.textContent=this.value"><output>${(k==='rivers'?s.riverCount:s[k])??v}</output>`)).join('')}</div><div class="notice">This is an artistic generator, not a hydrological or tectonic simulation. Edit coastlines and draw rivers to shape the geography your story needs.</div>`,btn('Random seed','random-seed')+btn('Generate','apply-generation','','accent'));}
function newWorldDialog(){modal('A new world',`<p class="muted">Pick a starting point. Every prompt, name and category is yours to change. Save your current world first if you want to keep it.</p><div class="template-grid">${Object.entries(GENRES).map(([k,g])=>btn(`<strong>${g.name}</strong><small>${g.tag}</small>`,'starter',`data-key="${k}"`)).join('')}</div>`);}
function newEntryDialog(){modal('Create a world entry',`<div class="fields">${field('Name','<input id="newEntryName" value="" placeholder="A person, place or idea…">')}${field('Category','<select id="newEntryType">'+options(types(),'Character')+'</select>')}</div>`,btn('Create entry','create-entry','','accent'));$('#newEntryName').focus();}
function relationDialog(id){modal('Connect your world',`<div class="fields">${field('From',`<select id="relFrom">${world.entries.map(e=>`<option value="${e.id}" ${id===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select>`)}${field('Relationship','<input id="relLabel" placeholder="trusts, belongs to, founded…">')}${field('To',`<select id="relTo">${world.entries.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select>`)}</div><p class="muted">Relationships are directional: who trusts whom can matter.</p>`,btn('Add relationship','create-relation','','accent'));}
function eventDialog(id){const e=world.events.find(e=>e.id===id)||{name:'',year:0,date:'',body:'',visibility:'Public',links:[]};modal(id?'Edit event':'New event',`<input id="eventId" type="hidden" value="${id||''}"><div class="fields">${field('Event name',`<input id="eventName" value="${esc(e.name)}">`)}${field('Year · negative years allowed',`<input id="eventYear" type="number" value="${e.year}">`)}${field('Date label · optional',`<input id="eventDate" value="${esc(e.date)}">`)}${field('Visibility','<select id="eventVisibility">'+options(['Public','Private'],e.visibility)+'</select>')}${field('What happened?',`<textarea id="eventBody" rows="5">${esc(e.body)}</textarea>`,true)}</div><details><summary>Linked entries</summary><div class="fields">${world.entries.map(x=>`<label class="check"><input type="checkbox" class="event-link" value="${x.id}" ${e.links.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></details>`,(id?btn('Delete event','delete-event',`data-id="${id}"`,'danger'):'')+btn('Save event','save-event','','accent'));}
function ask(title,callback,value=''){modal(title,'<input class="full-width" id="askValue" value="'+esc(value)+'">',btn('Save','ask-save','','accent'));$('#askValue').focus();window.askCallback=callback;}
function confirmDelete(title,fn){modal(title,'<p>This removes it from this world. You can undo afterwards.</p>',btn('Cancel','close-dialog')+btn('Remove','confirm-delete','','danger'));window.deleteCallback=fn;}
function exportDialog(){modal('Export your world',`<p class="muted">Keep an editable project, make a readable reference, or hand structured data to another tool.</p><div class="fields"><label class="check"><input type="checkbox" id="includeSecrets">Include private notes and events</label><label class="check"><input type="checkbox" id="canonOnly">Canon entries only</label></div><div class="grid">${btn('<strong>World bible</strong><br><small>Markdown text</small>','export-bible','data-format="md"')}${btn('<strong>Readable reference</strong><br><small>HTML · printable in a browser</small>','export-bible','data-format="html"')}${btn('<strong>Structured world data</strong><br><small>JSON with stable IDs and relationships</small>','export-data')}${btn('<strong>Reference bundle</strong><br><small>ZIP · text, maps, data and assets</small>','export-bundle')}${btn('<strong>Editable project</strong><br><small>.jagoworld · complete private world</small>','save')}${btn('<strong>Map exports</strong><br><small>SVG, PNG and map data</small>','export-map')}</div><p class="map-tip">Public references omit the dedicated private-note fields and private events. Check your main writing before sharing: secrets written in ordinary lore stay in that lore.</p>`);}
function mapExportDialog(){const m=currentMap();if(!m){toast('Create a map first.');return;}modal('Export '+m.name,`<p class="muted">SVG keeps vector shapes and labels editable in compatible software. PNG is a flattened image. JSON preserves objects and linked entry IDs.</p><div class="fields">${field('PNG width · pixels',`<input id="pngWidth" type="number" min="64" max="8192" value="${m.width}">`)}<label class="check"><input type="checkbox" id="pngTransparent">Transparent sea / background</label></div><div class="notice">Coordinates are fictional map units, not latitude and longitude. PNG size follows the map’s aspect ratio. Editing guides and selection handles are excluded.</div>`,btn('SVG artwork','download-map','data-format="svg"')+btn('PNG image','download-map','data-format="png"','accent')+btn('Map data JSON','download-map','data-format="json"'));}
function publicWorld(includeSecrets=false,canonOnly=false){const w=clone(world);if(!includeSecrets){w.notes='';w.entries.forEach(e=>e.secret='');w.events=w.events.filter(e=>e.visibility!=='Private');}if(canonOnly){w.entries=w.entries.filter(e=>e.status==='Canon');const ids=new Set(w.entries.map(e=>e.id));w.relations=w.relations.filter(r=>ids.has(r.from)&&ids.has(r.to));w.documents.forEach(d=>d.links=d.links.filter(id=>ids.has(id)));w.events.forEach(e=>e.links=e.links.filter(id=>ids.has(id)));w.maps.forEach(m=>m.objects.forEach(o=>{if(o.entryId&&!ids.has(o.entryId))o.entryId='';}));}return w;}
function exportSettings(){return {secrets:$('#includeSecrets')?.checked||false,canon:$('#canonOnly')?.checked||false};}
function bible(w){let out=`# ${w.name}\n\n${w.description}\n\n## Premise\n\n${w.premise}\n\nGenre: ${w.genre}\nTone: ${w.tone}\n\n`;for(const type of types()){const list=w.entries.filter(e=>e.type===type);if(!list.length)continue;out+='## '+type+'\n\n';for(const e of list){out+=`### ${e.name}\n\n${e.summary}\n\n${e.body}\n\n`;for(const [k,v]of Object.entries(e.fields))if(v)out+=`**${k}:** ${v}\n\n`;if(e.secret)out+='**Private notes:** '+e.secret+'\n\n';const rel=w.relations.filter(r=>r.from===e.id||r.to===e.id);for(const r of rel)out+=(w.entries.find(x=>x.id===r.from)?.name||'?')+' → '+r.label+' → '+(w.entries.find(x=>x.id===r.to)?.name||'?')+'\n\n';}}out+='## Timeline\n\n';for(const e of [...w.events].sort((a,b)=>a.year-b.year))out+=`### ${e.year} · ${e.name}\n\n${e.body}\n\n`;out+='## Writing\n\n';for(const d of [...w.documents].sort((a,b)=>a.order-b.order))out+=`### ${d.name}\n\n${d.body}\n\n`;if(w.notes)out+='## Working notes\n\n'+w.notes;return out;}
function referenceHTML(w){const text=bible(w);return `<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(w.name)}</title><style>body{max-width:900px;margin:50px auto;padding:0 25px;font:16px/1.8 Georgia,serif;color:#243834}h1,h2,h3{line-height:1.3}h2{border-top:1px solid #ccc;padding-top:24px;margin-top:35px}.line{white-space:pre-wrap}@media print{body{margin:0;max-width:none}h2{break-before:page}}</style><body>${text.split('\n').map(l=>{const m=l.match(/^(#{1,3}) (.*)/);return m?`<h${m[1].length}>${esc(m[2])}</h${m[1].length}>`:`<div class="line">${esc(l).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>')||'&nbsp;'}</div>`;}).join('')}<footer><p>Made with Jago Worldbuilding Studio.</p></footer></body></html>`;}
function download(name,data,type='application/octet-stream',project=false){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.append(a);if(project){pendingSave={url,signature:signature()};syncStatus();}a.click();a.remove();if(project&&!window.chrome?.webview){savedSignature=pendingSave.signature;pendingSave=null;syncStatus();toast('Project download requested. Keep the .jagoworld file somewhere safe.');}setTimeout(()=>URL.revokeObjectURL(url),120000);}
function saveProject(){download(slug(world.name)+'.jagoworld',JSON.stringify(world,null,2),'application/json',true);}
function mapData(m){return {format:'jago-world-map',version:1,worldId:world.id,coordinateSystem:'fictional-map-units',map:clone(m),entries:world.entries.filter(e=>m.objects.some(o=>o.entryId===e.id)).map(e=>({id:e.id,name:e.name,type:e.type})),assets:world.assets.filter(a=>m.background===a.id||m.objects.some(o=>o.assetId===a.id))};}
async function pngMap(m,width=1600,transparent=false){width=Math.round(clamp(width,64,8192));const height=Math.round(width*m.height/m.width);if(width*height>32000000)throw Error('Choose a smaller PNG size; exports are limited to 32 million pixels.');const blob=new Blob([mapSVG(m,{exporting:true,transparent})],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('The map could not be rendered. Try SVG export.'));img.src=url;});const c=document.createElement('canvas');c.width=width;c.height=height;c.getContext('2d').drawImage(img,0,0,width,height);return await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('PNG export failed.')),'image/png'));}finally{URL.revokeObjectURL(url);}}
function crc32(bytes){let n=~0;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=n&1?(n>>>1)^0xedb88320:n>>>1;}return(n^~0)>>>0;}
function zipFiles(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;for(const [name,content]of files){const nb=enc.encode(name),bytes=typeof content==='string'?enc.encode(content):content,crc=crc32(bytes),h=new Uint8Array(30+nb.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,nb.length,true);h.set(nb,30);chunks.push(h,bytes);const c=new Uint8Array(46+nb.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,nb.length,true);cv.setUint32(42,offset,true);c.set(nb,46);central.push(c);offset+=h.length+bytes.length;}const size=central.reduce((n,b)=>n+b.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
function bundle(){const settings=exportSettings(),w=publicWorld(settings.secrets,settings.canon),files=[['World-bible.md',bible(w)],['World-reference.html',referenceHTML(w)],['World-data.json',JSON.stringify(w,null,2)],['README.txt','Jago Worldbuilding Studio reference bundle\nMap SVG files are vector artwork; Map-data JSON files use fictional map coordinates and linked entry IDs.\nWorld-data.json can also be opened in Jago Worldbuilding Studio.\nPrivate notes included: '+settings.secrets+'\nCanon entries only: '+settings.canon+'\n']];for(const m of w.maps){const name=slug(m.name)+'-'+m.id.slice(0,8);files.push(['Maps/'+name+'.svg',mapSVG(m,{exporting:true})],['Maps/'+name+'.json',JSON.stringify({...mapData(m),entries:w.entries.filter(e=>m.objects.some(o=>o.entryId===e.id)).map(e=>({id:e.id,name:e.name,type:e.type}))},null,2)]);}for(const a of w.assets){const raw=atob(a.src.split(',')[1]);files.push(['Assets/'+slug(a.name)+'-'+a.id.slice(0,8)+'.png',Uint8Array.from(raw,c=>c.charCodeAt(0))]);}download(slug(w.name)+'-reference.zip',zipFiles(files));}
let recoveryDB=null;
async function openRecovery(){return new Promise(resolve=>{try{const req=indexedDB.open('jago-worldbuilding-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('worlds');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);}catch{resolve(null);}});}
async function readRecovery(){if(!recoveryDB)return null;return new Promise(resolve=>{try{const req=recoveryDB.transaction('worlds').objectStore('worlds').get('current');req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);}catch{resolve(null);}});}
function writeRecovery(){if(!recoveryDB){$('#saveStatus').textContent='Local recovery unavailable · save a project file';return;}try{const tx=recoveryDB.transaction('worlds','readwrite');tx.objectStore('worlds').put(clone(world),'current');tx.onerror=()=>{$('#saveStatus').textContent='Recovery storage full · save a project file';};}catch{toast('Local recovery failed. Save a project file to keep your work.');}}
function validateProject(w){const fail=m=>{throw Error(m);},str=(s,n=200000)=>typeof s==='string'&&s.length<=n,num=n=>Number.isFinite(n)&&Math.abs(n)<10000000,id=s=>typeof s==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(s),points=p=>Array.isArray(p)&&p.length<=10000&&p.every(q=>Array.isArray(q)&&q.length===2&&q.every(num));if(!w||w.format!=='jago-world-project'||w.version!==1||!id(w.id)||!str(w.name,300))fail('This is not a supported .jagoworld project.');for(const key of ['entries','documents','events','relations','maps','assets','customTypes'])if(!Array.isArray(w[key]))fail('Missing project section: '+key);if(w.entries.length>3000||w.documents.length>1000||w.maps.length>50||w.assets.length>100||w.events.length>5000||w.relations.length>10000)fail('The project exceeds this version’s capacity.');const used=new Set();const checkId=o=>{if(!id(o.id)||used.has(o.id))fail('Project IDs must be unique.');used.add(o.id);};for(const e of w.entries){checkId(e);if(!str(e.name,300)||!str(e.type,100)||!str(e.body)||!str(e.secret)||!str(e.summary)||!['Draft','Canon','Alternative'].includes(e.status)||!e.fields||typeof e.fields!=='object'||Array.isArray(e.fields)||!Array.isArray(e.tags)||e.tags.some(t=>!str(t,100)))fail('Invalid world entry.');for(const[k,v]of Object.entries(e.fields))if(!str(k,100)||!str(v))fail('Invalid entry field.');}for(const d of w.documents){checkId(d);if(!str(d.name,300)||!str(d.body)||!Array.isArray(d.links)||d.links.some(x=>!id(x))||!num(d.order))fail('Invalid document.');}for(const e of w.events){checkId(e);if(!str(e.name,300)||!num(e.year)||!str(e.body)||!Array.isArray(e.links)||!['Public','Private'].includes(e.visibility))fail('Invalid event.');}for(const r of w.relations){checkId(r);if(!id(r.from)||!id(r.to)||!str(r.label,300))fail('Invalid relationship.');}for(const a of w.assets){checkId(a);if(!str(a.name,300)||!/^data:image\/png;base64,[a-zA-Z0-9+/=]+$/.test(a.src)||a.src.length>24000000||!num(a.width)||!num(a.height)||a.width<1||a.height<1||a.width>4096||a.height>4096)fail('Invalid image asset.');}for(const m of w.maps){checkId(m);if(!str(m.name,300)||!THEMES[m.theme]||!num(m.width)||!num(m.height)||m.width<100||m.height<100||m.width>8192||m.height>8192||!Array.isArray(m.objects)||m.objects.length>5000)fail('Invalid map.');if(m.terrain){if(!Array.isArray(m.terrain.lands)||m.terrain.lands.length>100||m.terrain.lands.some(p=>!points(p))||!Array.isArray(m.terrain.decor)||m.terrain.decor.length>10000||m.terrain.decor.some(d=>!num(d.x)||!num(d.y)||!num(d.size))||(m.terrain.rivers&&!m.terrain.rivers.every(points)))fail('Invalid terrain.');}if(m.palette&&Object.entries(m.palette).some(([k,v])=>!['sea','land','mountain','forest','ink','route'].includes(k)||!/^#[a-f0-9]{6}$/i.test(v)))fail('Invalid map palette.');for(const o of m.objects){checkId(o);if(!['land','region','route','river','symbol','image','label'].includes(o.kind)||!['terrain','regions','routes','symbols','labels'].includes(o.layer))fail('Invalid map object.');if(o.points?!points(o.points):!num(o.x)||!num(o.y)||!num(o.size)||o.size<1||o.size>5000)fail('Invalid map coordinates in '+m.name+' / '+(o.displayName||o.symbol||o.kind)+' ('+JSON.stringify(o.points||[o.x,o.y,o.size])+').');if(o.color&&!/^#[a-f0-9]{6}$/i.test(o.color))fail('Invalid map colour.');if(o.label&&!str(o.label,500))fail('Invalid map label.');if(o.rotation!==undefined&&!num(o.rotation))fail('Invalid rotation.');if(o.opacity!==undefined&&(!num(o.opacity)||o.opacity<0||o.opacity>1))fail('Invalid opacity.');if(o.stroke!==undefined&&(!num(o.stroke)||o.stroke<.1||o.stroke>100))fail('Invalid line width.');}}for(const key of ['genre','description','premise','tone','calendar','notes'])if(!str(w[key]))fail('Invalid world setting.');if(w.customTypes.some(t=>!str(t,100)))fail('Invalid custom category.');return w;}
async function loadProject(file){if(file.size>80000000)throw Error('This file is too large (80 MB project limit).');const w=validateProject(JSON.parse(await file.text()));remember();world=w;selectedEntry=null;selectedDoc=null;selectedMap=null;mapSelection=null;mapViewport=null;mapDraft=[];entryFilter='All';listQuery='';docView='write';mapTool='select';$('#search').value='';$('#searchResults').innerHTML='';changed();savedSignature=signature();render();toast('World opened.');}
async function importAssets(files){if(world.assets.length+files.length>100)throw Error('This version supports up to 100 imported images.');const added=[];for(const f of files){if(f.size>20000000)throw Error('Each image must be under 20 MB.');const url=URL.createObjectURL(f),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Could not read '+f.name));img.src=url;});const scale=Math.min(1,4096/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);added.push({id:uid(),name:f.name.replace(/\.[^.]+$/,''),width:c.width,height:c.height,src:c.toDataURL('image/png')});}finally{URL.revokeObjectURL(url);}}if(added.some(a=>a.src.length>24000000))throw Error('This image needs a smaller size for a portable project. Use an image below 24 MB after conversion.');if(signature().length+added.reduce((n,a)=>n+a.src.length,0)>70000000)throw Error('This would exceed the portable project size. Use smaller images or remove unused assets.');mutate(()=>world.assets.push(...added));toast(added.length+' images added.');}
function help(){modal('A little guide to your world',`<div class="help-copy"><p>Start wherever an idea catches you. A person, a coastline, a small strange custom. There’s no correct order.</p><h3>World library</h3><p>Entries hold your people, places and ideas. Write their lore, fill in the useful prompts and add your own fields. Use <strong>[[Entry name]]</strong> in your writing to link to another entry. Draft, Canon and Alternative help you distinguish what you’re still exploring.</p><h3>Writing & time</h3><p>The writing desk holds references, outlines, chapters and scenes. Link the entries involved, or use the scene board to track progress. The timeline uses your own year numbering and date labels, including years before zero.</p><h3>Make a map</h3><p>Generate geography from a seed, or start drawing. Themes change the map’s visual character. Place symbols, add labels and draw land, regions, routes or rivers. Click to add shape points; press Enter to finish. Select an object to move it, resize it or connect it to lore. Selected paths show draggable points.</p><p>Paint mountains and forests by dragging. Edit coastlines converts generated land into editable shapes. Use the hand tool to pan, the mouse wheel to zoom and Fit to see the whole map. Imported assets can be placed as symbols or used as a background.</p><h3>Your world stays yours</h3><p>Save editable projects as <strong>.jagoworld</strong>. Local recovery keeps the last working world on this device; it is not a substitute for project backups. Undo and redo work across writing and map edits.</p><h3>Take it elsewhere</h3><p>Export maps as PNG, SVG or structured JSON. SVG retains shapes and labels in compatible vector software; images remain images. Map coordinates are fictional units, not GIS coordinates. Export world references as Markdown, printable HTML, JSON or a ZIP bundle. Dedicated private notes and private events are excluded unless you choose to include them.</p><p>You can import PNG map exports into Wobble, Dither and Repeat today. Send to studio carries maps and loops between all four apps. Tiled and Godot bundles provide artwork plus location and shape data.</p><h3>A few handy keys</h3><p><kbd>Ctrl S</kbd> Save · <kbd>Ctrl Z</kbd> Undo · <kbd>Ctrl Y</kbd> Redo · <kbd>Enter</kbd> Finish map shape · <kbd>Esc</kbd> Cancel shape · <kbd>Delete</kbd> Remove selected map object.</p><hr class="divider"><h3>Jago Worldbuilding Studio · 0.2.0</h3><p>Made by Cameron Jago Lis Illustrates.<br><strong>Open source. Free forever.</strong></p><p>A first working foundation, with plenty of room to grow. Genre starters are prompts, and the geography generator makes artistic starting points rather than simulating a real planet.</p></div>`);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){case'navigate':navigate(b.dataset.view);break;case'undo':undo();break;case'redo':redo();break;case'close-dialog':$('#dialog').close();break;case'help':help();break;case'new-world':newWorldDialog();break;case'starter':mutate(()=>{world=makeStarter(b.dataset.key);selectedEntry=null;selectedDoc=null;selectedMap=null;mapSelection=null;mapViewport=null;mapDraft=[];entryFilter='All';listQuery='';docView='write';mapTool='select';$('#search').value='';$('#searchResults').innerHTML='';view='home';savedSignature='';});$('#dialog').close();break;case'open-project':$('#projectFile').click();break;case'save':saveProject();break;case'export':exportDialog();break;case'new-entry':newEntryDialog();break;case'create-entry':{const name=$('#newEntryName').value.trim();if(!name){toast('Give your entry a name.');return;}mutate(()=>{const e=newEntry($('#newEntryType').value,name);world.entries.push(e);selectedEntry=e.id;entryFilter='All';listQuery='';entryTab='write';view='entries';});$('#dialog').close();break;}case'open-entry':selectedEntry=id;entryTab='write';navigate('entries');break;case'entry-tab':entryTab=b.dataset.tab;render();break;case'custom-field':ask('Add a field',name=>mutate(()=>{if(name)entry(selectedEntry).fields[name]='';}));break;case'custom-type':ask('Add an entry category',name=>mutate(()=>{if(name&&!types().includes(name))world.customTypes.push(name);}));break;case'ask-save':{const value=$('#askValue').value.trim().slice(0,100);$('#dialog').close();window.askCallback?.(value);break;}case'confirm-delete':$('#dialog').close();mutate(()=>window.deleteCallback?.());break;case'duplicate-entry':mutate(()=>{const copy=clone(entry(id));copy.id=uid();copy.name+=' (copy)';copy.created=copy.updated=Date.now();world.entries.push(copy);selectedEntry=copy.id;});break;case'delete-entry':confirmDelete('Remove this entry?',()=>{world.entries=world.entries.filter(e=>e.id!==id);world.relations=world.relations.filter(r=>r.from!==id&&r.to!==id);world.documents.forEach(d=>d.links=d.links.filter(x=>x!==id));world.events.forEach(e=>e.links=e.links.filter(x=>x!==id));world.maps.forEach(m=>m.objects.forEach(o=>{if(o.entryId===id)o.entryId='';}));selectedEntry=null;});break;case'export-entry':{const e=entry(id);download(slug(e.name)+'.md',`# ${e.name}\n\n${e.summary}\n\n${e.body}\n\n`+Object.entries(e.fields).filter(([k,v])=>v).map(([k,v])=>`**${k}:** ${v}`).join('\n\n'),'text/markdown');break;}case'new-relation':if(world.entries.length<2){toast('Create at least two entries to connect them.');return;}relationDialog(id);break;case'create-relation':{const from=$('#relFrom').value,to=$('#relTo').value,label=$('#relLabel').value.trim();if(from===to||!label){toast('Choose different entries and name the relationship.');return;}mutate(()=>world.relations.push({id:uid(),from,to,label}));$('#dialog').close();break;}case'delete-relation':mutate(()=>world.relations=world.relations.filter(r=>r.id!==id));break;case'new-doc':ask('Name your document',name=>mutate(()=>{if(!name)return;const d={id:uid(),name,kind:'Reference',status:'Draft',body:'',goal:'',conflict:'',links:[],order:world.documents.length};world.documents.push(d);selectedDoc=d.id;docView='write';view='writing';}),'Untitled document');break;case'open-doc':selectedDoc=id;docView='write';navigate('writing');break;case'toggle-board':docView=docView==='board'?'write':'board';render();break;case'read-doc':{const d=world.documents.find(d=>d.id===selectedDoc);modal(d.name,`<div class="body-preview">${bodyHtml(d.body)}</div>`);break;}case'export-doc':{const d=world.documents.find(d=>d.id===selectedDoc);download(slug(d.name)+'.md','# '+d.name+'\n\n'+d.body,'text/markdown');break;}case'delete-doc':confirmDelete('Remove this document?',()=>{world.documents=world.documents.filter(d=>d.id!==id);selectedDoc=null;});break;case'new-event':eventDialog();break;case'edit-event':eventDialog(id);break;case'save-event':{const name=$('#eventName').value.trim(),year=Number($('#eventYear').value);if(!name||!Number.isFinite(year)||Math.abs(year)>=10000000){toast('Add a name and a valid year.');return;}const data={id:$('#eventId').value||uid(),name,year,date:$('#eventDate').value,body:$('#eventBody').value,visibility:$('#eventVisibility').value,links:[...document.querySelectorAll('.event-link:checked')].map(x=>x.value)};mutate(()=>{const at=world.events.findIndex(x=>x.id===data.id);if(at>=0)world.events[at]=data;else world.events.push(data);});$('#dialog').close();break;}case'delete-event':mutate(()=>world.events=world.events.filter(e=>e.id!==id));$('#dialog').close();break;case'new-map':ask('Name your map',name=>mutate(()=>{if(!name)return;const m=makeMap(name);world.maps.push(m);selectedMap=m.id;view='maps';mapViewport=null;mapSelection=null;}),'New map');break;case'open-map':selectedMap=id;mapViewport=null;navigate('maps');break;case'map-tool':mapTool=b.dataset.tool;mapDraft=[];render();break;case'choose-symbol':mapSymbol=b.dataset.symbol;refreshMap();break;case'finish-shape':finishShape();break;case'map-zoom':zoomMap(Number(b.dataset.factor));break;case'map-fit':mapViewport=null;refreshMap();break;case'select-object':mapSelection=id;mapTool='select';render();break;case'duplicate-object':mutate(()=>{const o=clone(currentMap().objects.find(o=>o.id===mapSelection));o.id=uid();if(o.points)o.points=o.points.map(p=>[p[0]+30,p[1]+30]);else{o.x+=30;o.y+=30;}currentMap().objects.push(o);mapSelection=o.id;});break;case'delete-object':mutate(()=>{currentMap().objects=currentMap().objects.filter(o=>o.id!==mapSelection);mapSelection=null;});break;case'marker-entry':mutate(()=>{const o=currentMap().objects.find(o=>o.id===mapSelection),e=newEntry('Place',o.label||'Unnamed place');world.entries.push(e);o.entryId=e.id;o.label=e.name;});break;case'unlock-coasts':mutate(()=>{const m=currentMap(),t=mapTheme(m);for(const points of m.terrain?.lands||[])m.objects.unshift({id:uid(),kind:'land',points:clone(points),color:t.land,stroke:2,label:'Coastline',layer:'terrain'});if(m.terrain){m.terrain.lands=[];m.terrain.decor=[];m.terrain.rivers=[];}mapTool='select';});toast('Coastlines are now editable land shapes. Generated terrain marks were removed; you can paint new ones.');break;case'map-palette':{const m=currentMap(),t=mapTheme(m);modal('Map palette','<p class="muted">Customise the generated terrain and default colours for new objects. Existing objects keep their own colours.</p><div class="fields">'+['sea','land','mountain','forest','ink','route'].map(k=>field(k[0].toUpperCase()+k.slice(1),'<input type="color" id="palette-'+k+'" value="'+t[k]+'">')).join('')+'</div>',btn('Apply palette','apply-palette','','accent'));break;}case'apply-palette':mutate(()=>{currentMap().palette=Object.fromEntries(['sea','land','mountain','forest','ink','route'].map(k=>[k,$('#palette-'+k).value]));});$('#dialog').close();break;case'map-properties':{const m=currentMap();modal('Map properties',`<div class="fields">${field('Width · map units',`<input id="mapWidth" type="number" value="${m.width}" min="100" max="8192">`)}${field('Height · map units',`<input id="mapHeight" type="number" value="${m.height}" min="100" max="8192">`)}${field('Map notes',`<textarea id="mapNotes" rows="4">${esc(m.description||'')}</textarea>`,true)}</div><p class="muted">Changing dimensions proportionally scales the existing artwork to fit.</p>`,btn('Save properties','save-map-properties','','accent'));break;}case'save-map-properties':{const width=Number($('#mapWidth').value),height=Number($('#mapHeight').value),notes=$('#mapNotes').value;if(!Number.isInteger(width)||!Number.isInteger(height)||width<100||height<100||width>8192||height>8192){toast('Choose whole dimensions between 100 and 8192.');return;}mutate(()=>{const m=currentMap(),sx=width/m.width,sy=height/m.height,points=p=>p.map(q=>[q[0]*sx,q[1]*sy]);if(m.terrain){m.terrain.lands=m.terrain.lands.map(points);m.terrain.decor.forEach(d=>{d.x*=sx;d.y*=sy;d.size*=Math.sqrt(sx*sy);});m.terrain.rivers=(m.terrain.rivers||[]).map(points);}m.objects.forEach(o=>{if(o.points)o.points=points(o.points);else{o.x*=sx;o.y*=sy;o.size*=Math.sqrt(sx*sy);}});m.width=width;m.height=height;m.description=notes;mapViewport=null;});$('#dialog').close();break;}case'delete-map':confirmDelete('Remove this map?',()=>{world.maps=world.maps.filter(m=>m.id!==id);selectedMap=null;mapSelection=null;mapViewport=null;});break;case'generate-map':generationDialog();break;case'random-seed':$('#genSeed').value='world-'+Math.floor(Math.random()*999999);break;case'apply-generation':{const s={seed:$('#genSeed').value.slice(0,100),style:$('#genStyle').value,count:clamp(Number($('#genCount').value)||3,1,12),climate:$('#genClimate').value};for(const k of ['coverage','roughness','mountains','forests','rivers'])s[k]=+$('#gen-'+k).value;mutate(()=>currentMap().terrain=generateAdvanced(currentMap(),s));$('#dialog').close();break;}case'import-assets':$('#assetFiles').click();break;case'place-asset':case'background-asset':{if(!currentMap())mutate(()=>{const m=makeMap();world.maps.push(m);selectedMap=m.id;});mutate(()=>{const m=currentMap();if(a==='background-asset')m.background=id;else{const o={id:uid(),kind:'image',assetId:id,x:m.width/2,y:m.height/2,size:150,rotation:0,label:'',layer:'symbols'};m.objects.push(o);mapSelection=o.id;}view='maps';});break;}case'remove-background':mutate(()=>currentMap().background=null);break;case'delete-asset':confirmDelete('Remove this asset and its map placements?',()=>{world.assets=world.assets.filter(a=>a.id!==id);clearWorldKitArtwork(id);world.entries.forEach(e=>e.references=(e.references||[]).filter(x=>x!==id));world.maps.forEach(m=>{if(m.background===id)m.background=null;m.objects=m.objects.filter(o=>o.assetId!==id);});});break;case'export-bible':{const s=exportSettings(),w=publicWorld(s.secrets,s.canon),fmt=b.dataset.format;download(slug(w.name)+(fmt==='html'?'-reference.html':'-world-bible.md'),fmt==='html'?referenceHTML(w):bible(w),fmt==='html'?'text/html':'text/markdown');break;}case'export-data':{const s=exportSettings();download(slug(world.name)+'-world-data.json',JSON.stringify(publicWorld(s.secrets,s.canon),null,2),'application/json');break;}case'export-bundle':bundle();break;case'export-map':mapExportDialog();break;case'download-map':{const m=currentMap(),fmt=b.dataset.format,transparent=$('#pngTransparent').checked;if(fmt==='png'){b.disabled=true;const blob=await pngMap(m,Number($('#pngWidth').value)||m.width,transparent);download(slug(m.name)+'.png',blob);b.disabled=false;}else if(fmt==='svg')download(slug(m.name)+'.svg',mapSVG(m,{exporting:true,transparent}),'image/svg+xml');else download(slug(m.name)+'-map.json',JSON.stringify(mapData(m),null,2),'application/json');toast('Map export requested.');break;}}}catch(error){toast(error.message||'Something went wrong.');console.error(error);b.disabled=false;}});
document.addEventListener('change',event=>{const el=event.target;try{if(el.id==='entryFilter'){entryFilter=el.value;render();return;}if(el.id==='entrySearch'){listQuery=el.value;render();return;}if(el.id==='mapSelect'){selectedMap=el.value;mapViewport=null;mapSelection=null;render();return;}if(el.id==='worldName'){mutate(()=>world.name=el.value.trim().slice(0,300)||'Untitled world');return;}if(el.dataset.brush){if(el.dataset.brush==='size')brushSize=+el.value;else brushSpacing=+el.value;return;}if(el.dataset.mapShow){mapShow[el.dataset.mapShow]=el.checked;refreshMap();return;}if(el.dataset.entryAsset){mutate(()=>{const e=entry(selectedEntry);e.references=e.references||[];if(el.checked)e.references.push(el.dataset.entryAsset);else e.references=e.references.filter(id=>id!==el.dataset.entryAsset);});return;}if(el.dataset.linkScope){const d=world.documents.find(d=>d.id===selectedDoc);mutate(()=>{if(el.checked&&!d.links.includes(el.value))d.links.push(el.value);else if(!el.checked)d.links=d.links.filter(id=>id!==el.value);});return;}if(!el.dataset.scope)return;const scope=el.dataset.scope,key=el.dataset.field,target=scope==='world'?world:scope==='entry'?entry(selectedEntry):scope==='entry-custom'?entry(selectedEntry).fields:scope==='doc'?world.documents.find(d=>d.id===selectedDoc):scope==='map'?currentMap():scope==='object'?currentMap().objects.find(o=>o.id===mapSelection):null;if(!target)return;let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(key==='tags')value=el.value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,30);if(el.type==='number'&&!Number.isFinite(value)){toast('Please enter a valid number.');return;}if(scope==='object'){if(key==='size')value=clamp(value,1,5000);if(key==='opacity')value=clamp(value,0,1);if(key==='stroke')value=clamp(value,.1,100);if(key==='rotation')value=clamp(value,-36000,36000);}if(typeof value==='string')value=value.slice(0,['body','secret','summary','description','premise','notes'].includes(key)?200000:scope==='entry-custom'?200000:key==='name'?300:500);mutate(()=>{if(scope==='entry'&&key==='name'&&value!==target.name){const old='[['+target.name+']]',next='[['+value+']]';for(const e of world.entries)e.body=e.body.split(old).join(next);for(const d of world.documents)d.body=d.body.split(old).join(next);}target[key]=value;if(scope==='map'&&key==='theme'){target.palette={};const t=mapTheme(target);target.objects.forEach(o=>{if(!o.customColor)o.color=o.kind==='land'?t.land:o.kind==='river'?t.sea:o.kind==='route'?t.route:o.symbol==='forest'||o.kind==='region'?t.forest:o.symbol==='mountain'?t.mountain:t.ink;});}if(scope==='object'&&key==='color')target.customColor=true;if(scope==='entry'){target.updated=Date.now();if(key==='type')target.fields={...Object.fromEntries((PROMPTS[value]||PROMPTS.Custom).map(k=>[k,''])),...target.fields};}});}catch(e){toast(e.message);}});
$('#search').addEventListener('input',event=>{const q=event.target.value.trim().toLowerCase();$('#searchResults').innerHTML=q?[...world.entries.map(e=>({id:e.id,name:e.name,type:e.type,action:'open-entry',text:e.name+' '+e.body+' '+e.summary})),...world.documents.map(d=>({id:d.id,name:d.name,type:d.kind,action:'open-doc',text:d.name+' '+d.body}))].filter(x=>x.text.toLowerCase().includes(q)).slice(0,10).map(x=>btn(esc(x.name)+' <small>'+esc(x.type)+'</small>',x.action,`data-id="${x.id}"`)).join(''):'';});
$('#projectFile').onchange=async e=>{const f=e.target.files[0];if(f)try{await loadProject(f);}catch(error){toast(error.message);}e.target.value='';};$('#assetFiles').onchange=async e=>{try{await importAssets([...e.target.files]);}catch(error){toast(error.message);}e.target.value='';};
document.addEventListener('keydown',event=>{if(event.ctrlKey||event.metaKey){if(event.key.toLowerCase()==='s'){event.preventDefault();document.activeElement?.blur();saveProject();}if(event.key.toLowerCase()==='z'){event.preventDefault();document.activeElement?.blur();event.shiftKey?redo():undo();}if(event.key.toLowerCase()==='y'){event.preventDefault();document.activeElement?.blur();redo();}return;}if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||$('#dialog').open)return;if(view==='maps'){if(event.key==='Enter'&&mapDraft.length)finishShape();if(event.key==='Escape'){mapDraft=[];mapSelection=null;refreshMap();}if(event.key==='Delete'&&mapSelection)mutate(()=>{currentMap().objects=currentMap().objects.filter(o=>o.id!==mapSelection);mapSelection=null;});}});
window.addEventListener('beforeunload',event=>{if(world&&signature()!==savedSignature){event.preventDefault();event.returnValue='';}});
window.chrome?.webview?.addEventListener('message',event=>{const m=event.data;if(m.type==='project-save'&&pendingSave&&m.url===pendingSave.url){if(m.ok){savedSignature=pendingSave.signature;toast('Project file saved.');}else toast('Save cancelled. Your working world is still here.');pendingSave=null;syncStatus();}});
window.checkUnsaved=()=>!!world&&signature()!==savedSignature;
window.JagoWorld={get world(){return world;},get view(){return view;},navigate,makeStarter,makeMap,generateAdvanced,validateProject,mapSVG,pngMap,bible,publicWorld,mapData,zipFiles,loadProject,mutate,undo,redo,saveProject,signature,importAssets,setWorld(w){world=validateProject(w);selectedEntry=selectedDoc=selectedMap=null;mapSelection=null;mapViewport=null;history=[];future=[];savedSignature='';render();},get ready(){return !!world;}};
(async()=>{recoveryDB=await openRecovery();const recovered=await readRecovery();if(recovered)try{world=validateProject(recovered);}catch{world=null;}if(!world)world=makeStarter('fantasy');render();if(recovered&&world===recovered)toast('Your last working world has been recovered.');window.appReady=true;})();

